-- Real SQLite/PostgreSQL: one structure, three service levels
CREATE INDEX idx_enr_course_done ON enrollments(course_id, completed);

-- Fully served (both columns anchor the search)
-- SELECT * FROM enrollments WHERE course_id = 5 AND completed = 1;
-- Prefix-served (course_id anchors; completed filters the slice)
-- SELECT * FROM enrollments WHERE course_id = 5;
-- UNSERVED (completed alone cannot enter the structure)
-- SELECT * FROM enrollments WHERE completed = 1;

-- Real PostgreSQL: keys search, INCLUDE payload rides along
-- CREATE INDEX idx_enr_cover ON enrollments(course_id) INCLUDE (progress, completed);
-- SELECT progress, completed FROM enrollments WHERE course_id = 5;
-- → index-only scan: table never touched.

-- Real SQLite: same idea, wider composite (no INCLUDE syntax)
CREATE INDEX idx_enr_cover_lite ON enrollments(course_id, progress, completed);

-- Real SQLite/PostgreSQL: index only what the hot queries read
CREATE INDEX idx_enr_incomplete ON enrollments(course_id) WHERE completed = 0;

-- Served: predicate matches the partial condition exactly
-- SELECT * FROM enrollments WHERE course_id = 5 AND completed = 0;
-- IGNORED: predicate differs — planner cannot use the slice
-- SELECT * FROM enrollments WHERE course_id = 5 AND completed = 1;

